 function exportSavedSession(item:any){
  // An archived attempt is portable; only its own simulation state is exported.
  const payload={format:'clinicaai-saved-attempt',version:1,attempt:item};
  const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'});
  const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;
  link.download='clinicaai-attempt-'+String(item.id||'demo').replace(/[^a-zA-Z0-9_-]/g,'').slice(0,40)+'.json';
  link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
 }
 async function importSavedSession(file?:File){
  if(!file)return;
  if(file.size>2_000_000){window.alert(language==='en'?'File too large (2 MB maximum).':'Fichier trop volumineux (2 Mo maximum).');return;}
  try{
   const raw=JSON.parse(await file.text());const item=raw?.format==='clinicaai-saved-attempt'?raw.attempt:raw;
   if(!item||!item.data||!Array.isArray(item.data.chat)||!Array.isArray(item.data.tests)||!Number.isInteger(item.data.caseIndex)||item.data.caseIndex<0||item.data.caseIndex>=cases.length)throw Error('Invalid attempt format');
   const safe={id:'imported-'+Date.now(),name:String(item.name||'Imported clinical attempt').slice(0,90),data:item.data,updatedAt:Date.now()};
   const next=[safe,...savedSessions].slice(0,20);
   localStorage.setItem(ARCHIVE_KEY,JSON.stringify(next));setSavedSessions(next);
   window.alert(language==='en'?'Attempt imported. Choose Restore full attempt / edit.':'Essai importé. Cliquez sur Restaurer l’essai complet / modifier.');
  }catch{window.alert(language==='en'?'Unable to import this attempt JSON.':'Impossible d’importer ce fichier JSON d’essai.');}
 }
