 function restoreWholeCase(){if(!window.confirm('Restaurer ce cas clinique complet pour le modifier ? Les réponses sont conservées, les corrections devront être actualisées après modification.'))return;setFinished(false);setSmartResult(null);setGrading(false);setClockRunning(false);setSessionNonce(n=>n+1)}

