 function reset(i=caseIndex){setActiveSessionId(null);setGeminiHistoryGrade(null);setGeminiExamsGrade(null);try{localStorage.removeItem(DRAFT_KEY);for(const k of Object.keys(localStorage)){if(k.startsWith('clinicaai-v46-section-'))localStorage.removeItem(k)}}catch{}compareRequest.current++;setSessionNonce(v=>v+1);setClockRunning(false);setExamMode(false);setClockExpired(false);setRemaining(duration*60);setSmartResult(null);setGrading(false);setClinicalAnswers({triage:'',diagnosis:'',management:''});setCaseIndex(i);setMessage('');setChat([]);setVisited([]);setTests([]);setExamsValidated(false);setHistoryValidated(false);setChecks([]);setDx('');setAction('');setFinished(false);setDiagnosticStep(0);setHypothesisText('');setHypothesisSelections([]);setPrimaryDiagnosis('');setDiagnosticLocked(false);setAiDiagnosticGrade(null);setAiDiagnosticError('');setAiDiagnosticLoading(false)}
