 function deleteHistoryExchange(index:number){
  if(busy||finished)return;
  if(chat[index]?.role!=='student')return;
  const question=chat[index].text;
  if(!window.confirm(language==='en'?'Delete this question and its patient reply?':'Supprimer cette question et sa réponse du patient ?'))return;
  const updated=chat.filter((entry,i)=>i!==index&&i!==index+1);
  // Rebuild coverage from surviving questions instead of retaining points from deleted questions.
  const nextVisited=[...new Set(updated.filter((entry,i)=>entry.role==='student'&&updated[i+1]?.role==='patient').flatMap(entry=>historyTopicsForQuestion(current,entry.text,language)))];
  setChat(updated);
  setVisited(nextVisited);
  setHistoryValidated(false);setGeminiHistoryGrade(null);
  setSmartResult(null);
 }
 async function send(e){
  e.preventDefault();
  if(!message.trim()||finished||busy)return;
  const question=message.trim(),requestId=++compareRequest.current;
  setMessage('');setBusy(true);setAiError('');
  // The patient has one answer only, generated independently of local teaching evaluation.
  try{
   const response=await fetch('/api/history-gemini',{
    method:'POST',headers:{'Content-Type':'application/json'},
    body:JSON.stringify({caseIndex,question,language})
   });
   const data=await response.json();
   if(!response.ok||typeof data.answer!=='string'||!data.answer.trim())
    throw new Error(data.error||'Generative AI unavailable');
   if(requestId!==compareRequest.current)return;
   // This local assessment is used only for the hidden teaching tip, not as a patient answer.
   setChat(v=>[...v,{role:'student',text:question},{role:'patient',text:data.answer.trim()}]);
   const covered=historyTopicsForQuestion(current,question,language);
   if(covered.length)setVisited(v=>[...new Set([...v,...covered])]);setGeminiHistoryGrade(null);
  }catch(error){
   if(requestId===compareRequest.current){
    const notice=language==='en'?'The virtual patient is temporarily unavailable. No response was generated.':'Le patient virtuel est temporairement indisponible. Aucune réponse n’a été générée.';
    setChat(v=>[...v,{role:'student',text:question},{role:'system',text:notice}]);
    setAiError(error.message||notice);
   }
  }finally{if(requestId===compareRequest.current)setBusy(false)}
 }
